#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size(), off = n + 1;
    vector<vector<int>> positions(26);
    for (int i = 0; i < n; i++) positions[s[i] - 'a'].push_back(i);
    // seen[balance + off] counts earlier prefix balances; touched lists the slots to reset.
    vector<long long> seen(2 * n + 3, 0);
    vector<int> touched;
    auto reset = [&]() {
        for (int t : touched) seen[t] = 0;
        touched.clear();
        seen[off] = 1;
        touched.push_back(off);
    };
    auto add = [&](int balance) -> long long {
        int key = balance + off;
        long long before = seen[key];
        if (before == 0) touched.push_back(key);
        seen[key]++;
        return before;
    };
    long long answer = 0;
    // Substrings where character c makes up exactly half: c is +1, others -1, equal prefix sums.
    for (int c = 0; c < 26; c++) {
        if (positions[c].empty()) continue;
        reset();
        int balance = 0;
        for (char v : s) {
            balance += (v - 'a' == c) ? 1 : -1;
            answer += add(balance);
        }
    }
    // Substrings made only of two characters in equal numbers were counted twice.
    for (int a = 0; a < 26; a++) {
        for (int b = 0; b < a; b++) {
            const auto &x = positions[a], &y = positions[b];
            if (x.empty() || y.empty()) continue;
            size_t i = 0, j = 0;
            int previous = -2, balance = 0;
            while (i < x.size() || j < y.size()) {
                int p, step;
                if (j == y.size() || (i < x.size() && x[i] < y[j])) p = x[i++], step = 1;
                else p = y[j++], step = -1;
                if (p != previous + 1) {
                    balance = 0;
                    reset();
                }
                balance += step;
                answer -= add(balance);
                previous = p;
            }
        }
    }
    cout << answer << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    static long[] seen;
    static int[] touched;
    static int touchedCount, off;

    static void reset() {
        for (int t = 0; t < touchedCount; t++) seen[touched[t]] = 0;
        touchedCount = 0;
        seen[off] = 1;
        touched[touchedCount++] = off;
    }

    // Returns how many earlier prefixes had this balance, then records it.
    static long add(int balance) {
        int key = balance + off;
        long before = seen[key];
        if (before == 0) touched[touchedCount++] = key;
        seen[key]++;
        return before;
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        off = n + 1;
        seen = new long[2 * n + 3];
        touched = new int[2 * n + 3];
        int[][] positions = new int[26][];
        int[] counts = new int[26];
        for (int i = 0; i < n; i++) counts[s.charAt(i) - 'a']++;
        for (int c = 0; c < 26; c++) positions[c] = new int[counts[c]];
        int[] fill = new int[26];
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            positions[c][fill[c]++] = i;
        }
        long answer = 0;
        // Substrings where character c makes up exactly half: c is +1, others -1, equal prefix sums.
        for (int c = 0; c < 26; c++) {
            if (counts[c] == 0) continue;
            reset();
            int balance = 0;
            for (int i = 0; i < n; i++) {
                balance += (s.charAt(i) - 'a' == c) ? 1 : -1;
                answer += add(balance);
            }
        }
        // Substrings made only of two characters in equal numbers were counted twice.
        for (int a = 0; a < 26; a++) {
            for (int b = 0; b < a; b++) {
                int[] x = positions[a], y = positions[b];
                if (x.length == 0 || y.length == 0) continue;
                int i = 0, j = 0, previous = -2, balance = 0;
                while (i < x.length || j < y.length) {
                    int p, step;
                    if (j == y.length || (i < x.length && x[i] < y[j])) {
                        p = x[i++];
                        step = 1;
                    } else {
                        p = y[j++];
                        step = -1;
                    }
                    if (p != previous + 1) {
                        balance = 0;
                        reset();
                    }
                    balance += step;
                    answer -= add(balance);
                    previous = p;
                }
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	s := readToken()
	n := len(s)
	off := n + 1
	positions := make([][]int, 26)
	for i := 0; i < n; i++ {
		c := s[i] - 'a'
		positions[c] = append(positions[c], i)
	}
	// seen[balance+off] counts earlier prefix balances; touched lists the slots to reset.
	seen := make([]int, 2*n+3)
	touched := make([]int, 0, 2*n+3)
	reset := func() {
		for _, t := range touched {
			seen[t] = 0
		}
		touched = touched[:0]
		seen[off] = 1
		touched = append(touched, off)
	}
	add := func(balance int) int {
		key := balance + off
		before := seen[key]
		if before == 0 {
			touched = append(touched, key)
		}
		seen[key]++
		return before
	}
	answer := 0
	// Substrings where character c makes up exactly half: c is +1, others -1, equal prefix sums.
	for c := 0; c < 26; c++ {
		if len(positions[c]) == 0 {
			continue
		}
		reset()
		balance := 0
		for i := 0; i < n; i++ {
			if int(s[i]-'a') == c {
				balance++
			} else {
				balance--
			}
			answer += add(balance)
		}
	}
	// Substrings made only of two characters in equal numbers were counted twice.
	for a := 0; a < 26; a++ {
		for b := 0; b < a; b++ {
			x, y := positions[a], positions[b]
			if len(x) == 0 || len(y) == 0 {
				continue
			}
			i, j, previous, balance := 0, 0, -2, 0
			for i < len(x) || j < len(y) {
				var p, step int
				if j == len(y) || (i < len(x) && x[i] < y[j]) {
					p, step = x[i], 1
					i++
				} else {
					p, step = y[j], -1
					j++
				}
				if p != previous+1 {
					balance = 0
					reset()
				}
				balance += step
				answer -= add(balance)
				previous = p
			}
		}
	}
	fmt.Println(answer)
}
